Per R9, this script sends SMS. It reads the gateway's delivery status and the
original sent messages, and re-queues each failed message to the same household
with the same template and params. Delivered messages (and messages with no
status entry) are never resent.
"""

import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent))

from notifications.sms import delivery_status, queue_sms, sent_messages


def main() -> None:
    status = delivery_status()
    originals = {m.id: m for m in sent_messages()}

    failed_ids = [sid for sid, s in status.items() if s == "failed"]
    for sid in failed_ids:
        m = originals.get(sid)
        if m is None:
            continue
        try:
            queue_sms(m.household_id, m.template_id, m.params)
        except (ValueError, RuntimeError):
            # Household opted out of SMS since the original send, or SMS is disabled.
            continue


if __name__ == "__main__":
    main()
